  attr :nombre, :string, required: true
  attr :class, :any, default: nil

  @doc "El ícono, decorativo: el nombre va siempre al lado."
  def icono(assigns) do
    assigns = assign(assigns, trazos: Map.get(@trazos, assigns.nombre, []))

    ~H"""
    <svg
      class={["icono-tema", @class]}
      viewBox="0 0 15 15"
      width="18"
      height="18"
      fill="currentColor"
      aria-hidden="true"
    >
      <path :for={d <- @trazos} d={d} />
    </svg>
    """
  end

  @doc "Los trazos de todos, para dibujarlos en el plano."
  def trazos, do: @trazos
end
